(OUT/'publish.py').write_text((src/'publish.py').read_text(encoding='utf8').replace("identity='early_target_parts_20261114'","identity='auto_prior_masks_20261114'").replace("'scores.npz','predictions.npz','prior_parts.npz'","'prompts.npz','predictions.npz','all_teacher_masks.npz'"),encoding='utf8')
